def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = next(v for v in range(1, 10) if any(
        all(x == v for x in row) for row in grid
    ))

    def bands(n, is_separator):
        result = []
        start = 0
        for i in range(n):
            if is_separator(i):
                if start < i:
                    result.append((start, i))
                start = i + 1
        if start < n:
            result.append((start, n))
        return result

    rb = bands(h, lambda r: all(x == sep for x in grid[r]))
    cb = bands(w, lambda c: all(grid[r][c] == sep for r in range(h)))
    out = [row[:] for row in grid]
    colors = {x for row in grid for x in row if x not in (0, sep)}

    for color in colors:
        def pattern(i, j):
            r0, r1 = rb[i]
            c0, c1 = cb[j]
            return [[grid[r][c] == color for c in range(c0, c1)]
                    for r in range(r0, r1)]

        def occupied(p):
            return any(any(row) for row in p)

        def mirror(p):
            return [row[::-1] for row in p]

        # Find adjacent cells that establish a horizontally mirrored pair.
        pairs = set()
        for i in range(len(rb)):
            for j in range(len(cb) - 1):
                a, b = pattern(i, j), pattern(i, j + 1)
                if occupied(a) and occupied(b) and mirror(a) == b:
                    pairs.add(j)

        # Extend the established mirrored pair to every other row band.
        for j in pairs:
            for i in range(len(rb)):
                a, b = pattern(i, j), pattern(i, j + 1)
                if not occupied(a) and not occupied(b):
                    continue
                for source, target_j in ((a, j + 1), (b, j)):
                    target = mirror(source)
                    r0, r1 = rb[i]
                    c0, c1 = cb[target_j]
                    for y, row in enumerate(target):
                        for x, filled in enumerate(row):
                            if filled and r0 + y < r1 and c0 + x < c1:
                                out[r0 + y][c0 + x] = color

    return out
